dunes-script-module.script:
const method = "GET";
const url = "/v1/bundles/" + bundleId;
const contentType = "application/json";

const content = {
    "bundleDownloadSpec": {
        "downloadNow": true
    }
};

var request = restHost.createRequest(method, url, JSON.stringify(content));
request.contentType = contentType;
request.setHeader("Authorization", "Bearer " + installerToken);

var response = request.execute();

var statusCode = response.statusCode;
System.log("Status code: " + statusCode);

var contentAsString = response.contentAsString;

// Kontrollera om anropet lyckades med en 20x-statuskod (200–299)
if (statusCode >= 200 && statusCode < 300) {
    try {
        var parsedResponse = JSON.parse(contentAsString);
        return parsedResponse.downloadStatus || null;
    } catch (e) {
        System.error("Misslyckades att parsa JSON-svaret: " + e);
        return null;
    }
} else {
    System.error("Anropet misslyckades med statuskod: " + statusCode);
    return null;
}
